                  setGradeClerkLimit((limits) => ({ ...limits, [grade]: value }));
                  touch(key);
                }}
                // As the policy date: clearing an already blank field must still send the blank.
                onFocus={() => touch(key)}
              />
            </label>{' '}
            {from(key)}
            now <span data-testid={`setting-${key}-current`}><Fig>{data?.[field] ?? ''}</Fig></span>{' '}
          </span>
        ))}
""",1)
open(p,'w').write(s)
EOF
